CREATE OR REPLACE FUNCTION public.claim_agent_handoff(_id uuid, _token uuid) RETURNS SETOF public.whatsapp_handoffs LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.whatsapp_handoffs h SET status='sending',claim_token=_token,attempts=attempts+1,updated_at=clock_timestamp() WHERE h.id=_id AND h.status='pending' AND h.attempts<5 AND h.next_attempt_at<=now() AND EXISTS(SELECT 1 FROM public.whatsapp_agents a WHERE a.id=h.agent_id AND a.status='active' AND a.melhorias_enabled AND a.handoff_enabled AND a.report_profile='generico') RETURNING h.*; $$;
REVOKE ALL ON FUNCTION public.claim_agent_handoff(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_agent_handoff(uuid,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.drain_agent_recovery() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j bigint; BEGIN PERFORM pg_advisory_xact_lock(hashtext('agent-recovery-schedule')); IF NOT EXISTS(SELECT 1 FROM public.whatsapp_conversas c JOIN public.whatsapp_agents a ON a.id=c.agent_id WHERE c.reply_state IN ('received','processing','failed','sending') AND c.created_at>now()-interval '6 hours' AND c.recovered_at IS NULL AND a.melhorias_enabled AND a.watchdog_enabled AND a.status='active' AND a.ai_paused_reason IS NULL) AND NOT EXISTS(SELECT 1 FROM public.whatsapp_handoffs h JOIN public.whatsapp_agents a ON a.id=h.agent_id WHERE h.status IN ('pending','sending') AND h.attempts<5 AND a.status='active' AND a.melhorias_enabled AND a.handoff_enabled) THEN FOR j IN SELECT jobid FROM cron.job WHERE jobname='agent-recovery-while-pending' LOOP PERFORM cron.unschedule(j); END LOOP; END IF; END $$;
REVOKE ALL ON FUNCTION public.drain_agent_recovery() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.drain_agent_recovery() TO service_role;